function formatTranslation(key, replacements = {}, langCode = currentLang) {
    let value = String(resolveTranslation(key, langCode));
    for (const [name, replacement] of Object.entries(replacements)) {
        value = value.replaceAll(`{${name}}`, String(replacement));
    }
    return value;
}



