for (const [code, phrases] of Object.entries(defenderSignInProtectionTranslations)) {
    if (!translations[code]) translations[code] = { ...translations["en-US"] };
    Object.assign(translations[code], phrases);
}

function resolveTranslation(key, langCode = currentLang) {
    const exact = translations[langCode];
    if (exact && exact[key] !== undefined) return exact[key];

    const base = String(langCode || '').split('-')[0].toLowerCase();
    const siblingCode = Object.keys(translations).find(code => code.split('-')[0].toLowerCase() === base);
    if (siblingCode && translations[siblingCode]?.[key] !== undefined) return translations[siblingCode][key];

    return translations['en-US']?.[key] ?? key;
}

let englishPhraseIndex = null;
function getEnglishPhraseIndex() {
    if (!englishPhraseIndex) {
        englishPhraseIndex = new Map();
        for (const [key, value] of Object.entries(translations['en-US'] || {})) {
            if (typeof value === 'string' && value.trim() && !value.includes('{')) {
                englishPhraseIndex.set(value, key);
            }
        }
    }
    return englishPhraseIndex;
}

function translateKnownPhrase(text, langCode = currentLang) {
    if (typeof text !== 'string' || !text.trim()) return text;
    const key = getEnglishPhraseIndex().get(text);
    return key ? resolveTranslation(key, langCode) : text;
}

const autoLocalizedTextSources = new WeakMap();
const AUTO_LOCALIZED_ATTRIBUTES = ['placeholder', 'title', 'aria-label', 'alt'];
let localizationApplying = false;

function shouldSkipAutomaticLocalization(element) {
    if (!(element instanceof Element)) return true;
    if (isTranslationProtected(element)) return true;
    if (element.closest('script, style, noscript, textarea, code, pre')) return true;
    return false;
}

function localizeAutomaticTextNode(textNode) {
    if (!(textNode instanceof Text) || !textNode.parentElement) return;
    const parent = textNode.parentElement;
    if (shouldSkipAutomaticLocalization(parent)) return;
    if (parent.closest('[data-i18n]')) return;

    const raw = textNode.nodeValue ?? '';
    if (!raw.trim()) return;
    if (!autoLocalizedTextSources.has(textNode)) autoLocalizedTextSources.set(textNode, raw);
    const source = autoLocalizedTextSources.get(textNode);
    const trimmed = source.trim();
    const translated = translateKnownPhrase(trimmed);
    if (translated === trimmed && currentLang !== 'en-US') return;

    const leading = source.match(/^\s*/)?.[0] ?? '';
    const trailing = source.match(/\s*$/)?.[0] ?? '';
    const nextValue = `${leading}${translated}${trailing}`;
    if (textNode.nodeValue !== nextValue) textNode.nodeValue = nextValue;
}

function applyAutomaticTextTranslations(root = document) {
    const roots = [];
    if (root instanceof Text) {
        localizeAutomaticTextNode(root);
        return;
    }
    if (root instanceof Element || root instanceof Document || root instanceof DocumentFragment) roots.push(root);
    for (const base of roots) {
        const walker = document.createTreeWalker(base, NodeFilter.SHOW_TEXT, {
            acceptNode(node) {
                return node.parentElement && !shouldSkipAutomaticLocalization(node.parentElement)
                    ? NodeFilter.FILTER_ACCEPT
                    : NodeFilter.FILTER_REJECT;
            }
        });
        let node;
        while ((node = walker.nextNode())) localizeAutomaticTextNode(node);
    }
}

function applyAutomaticAttributeTranslations(root = document) {
    const elements = [];
    if (root instanceof Element) elements.push(root);
    if (root.querySelectorAll) elements.push(...root.querySelectorAll('*'));

    for (const el of elements) {
        if (shouldSkipAutomaticLocalization(el)) continue;
        for (const attr of AUTO_LOCALIZED_ATTRIBUTES) {
            const explicit = attr === 'aria-label' ? 'data-i18n-aria-label' : `data-i18n-${attr}`;
            if (el.hasAttribute(explicit) || !el.hasAttribute(attr)) continue;
            const sourceAttr = `data-i18n-auto-${attr.replace(/[^a-z0-9_-]/gi, '-')}`;
            if (!el.hasAttribute(sourceAttr)) el.setAttribute(sourceAttr, el.getAttribute(attr) || '');
            const source = el.getAttribute(sourceAttr) || '';
            const translated = translateKnownPhrase(source);
            if (translated && el.getAttribute(attr) !== translated) el.setAttribute(attr, translated);
        }
    }
}

function isTranslationProtected(element) {
    if (!(element instanceof Element)) return false;
    return Boolean(
        element.closest('[data-i18n-preserve="true"]') ||
        element.closest('[data-user-defined-text="true"]')
    );
}

function setUserDefinedText(target, value) {
    const elements = typeof target === 'string'
        ? Array.from(document.querySelectorAll(target))
        : target instanceof Element
            ? [target]
            : Array.from(target || []);

    elements.forEach(el => {
        if (!(el instanceof Element)) return;
        el.setAttribute('data-user-defined-text', 'true');
        el.setAttribute('data-i18n-preserve', 'true');
        el.textContent = String(value ?? '');
    });
}

function clearUserDefinedTextProtection(target) {
    const elements = typeof target === 'string'
        ? Array.from(document.querySelectorAll(target))
        : target instanceof Element
            ? [target]
            : Array.from(target || []);

    elements.forEach(el => {
        if (!(el instanceof Element)) return;
        el.removeAttribute('data-user-defined-text');
        el.removeAttribute('data-i18n-preserve');
    });
}

function getSavedAccountName() {
    return localStorage.getItem('webwindows_account_name')
        || localStorage.getItem('win12_account_name')
        || '';
}

function applySavedAccountName(root = document) {
    const savedName = getSavedAccountName();
    if (!savedName) return;

    const names = [];
    if (root instanceof Element && root.matches('.user-name')) names.push(root);
    if (root.querySelectorAll) names.push(...root.querySelectorAll('.user-name'));

    setUserDefinedText(names, savedName);

    const nameInput = document.getElementById('settings-name-input');
    if (nameInput) nameInput.value = savedName;
}

function applyTranslationAttributes(root = document) {
    const nodes = [];
    if (root instanceof Element && root.matches('[data-i18n], [data-i18n-placeholder], [data-i18n-title], [data-i18n-aria-label], [data-i18n-alt]')) nodes.push(root);
    if (root.querySelectorAll) nodes.push(...root.querySelectorAll('[data-i18n], [data-i18n-placeholder], [data-i18n-title], [data-i18n-aria-label], [data-i18n-alt]'));

    nodes.forEach(el => {
        // Custom/user-authored names must not be replaced by a language pack.
        if (isTranslationProtected(el)) return;

        const key = el.getAttribute('data-i18n');
        if (key) {
            const value = resolveTranslation(key);
            if (el.tagName === 'INPUT' && el.hasAttribute('placeholder')) el.placeholder = value;
            else el.textContent = value;
        }
        const placeholderKey = el.getAttribute('data-i18n-placeholder');
        if (placeholderKey) el.setAttribute('placeholder', resolveTranslation(placeholderKey));
        const titleKey = el.getAttribute('data-i18n-title');
        if (titleKey) el.setAttribute('title', resolveTranslation(titleKey));
        const ariaKey = el.getAttribute('data-i18n-aria-label');
        if (ariaKey) el.setAttribute('aria-label', resolveTranslation(ariaKey));
        const altKey = el.getAttribute('data-i18n-alt');
        if (altKey) el.setAttribute('alt', resolveTranslation(altKey));
    });

    applyAutomaticTextTranslations(root);
    applyAutomaticAttributeTranslations(root);
}

let localizationObserver = null;
function startLocalizationObserver() {
    if (localizationObserver || !document.body) return;
    localizationObserver = new MutationObserver(mutations => {
        if (localizationApplying) return;
        localizationApplying = true;
        try {
            for (const mutation of mutations) {
                mutation.addedNodes.forEach(node => {
                    if (node.nodeType === Node.ELEMENT_NODE) {
                        applyTranslationAttributes(node);
                        applySavedAccountName(node);
                    } else if (node.nodeType === Node.TEXT_NODE) {
                        applyAutomaticTextTranslations(node);
                    }
                });
            }
        } finally {
            localizationApplying = false;
        }
    });
    localizationObserver.observe(document.body, { childList: true, subtree: true });
}

function applyLanguageDirection(langCode = currentLang) {
    const profile = builtInLanguageRegistry.find(item => item.code === langCode);
    const direction = profile?.direction || 'ltr';
    document.documentElement.lang = langCode;
    document.documentElement.dir = direction;
    document.body?.classList.toggle('rtl-ui', direction === 'rtl');
}


