        function setSearchLocation(loc, save=true) {
            searchLocation = loc;
            const searchAnchor = document.getElementById('search-wrapper'); 
            const deskAnchor = document.getElementById('desktop-search-anchor');
            const tbAnchor = document.getElementById('taskbar-search-anchor');
            const searchDropdown = document.getElementById('search-dropdown');

            if (loc === 'taskbar') {
                if(searchAnchor && tbAnchor) {
                    searchAnchor.classList.add('in-taskbar-mode');
                    tbAnchor.appendChild(searchAnchor);
                }
                if(searchDropdown) searchDropdown.classList.add('taskbar-mode');
            } else {
                if(searchAnchor && deskAnchor) {
                    searchAnchor.classList.remove('in-taskbar-mode');
                    deskAnchor.appendChild(searchAnchor);
                }
                if(searchDropdown) searchDropdown.classList.remove('taskbar-mode');
            }
            if(save) localStorage.setItem('win12_searchloc', loc);
        }
