    let disclaimerTimerInterval;

    // Triggers the countdown block
    function startDisclaimerTimer(seconds) {
        const input = document.getElementById('defender-disclaimer-input');
        const btn = document.getElementById('defender-disclaimer-submit');
        let timeLeft = seconds;

        // Lock the inputs
        input.disabled = true;
        input.value = "";
        btn.disabled = true;
        btn.classList.add('opacity-50', 'cursor-not-allowed');

        clearInterval(disclaimerTimerInterval);
        input.placeholder = `Please read the disclaimer... (${timeLeft}s)`;

        disclaimerTimerInterval = setInterval(() => {
            timeLeft--;
            if (timeLeft > 0) {
                input.placeholder = `Please read the disclaimer... (${timeLeft}s)`;
            } else {
                // Unlock!
                clearInterval(disclaimerTimerInterval);
                input.disabled = false;
                input.placeholder = "Type Yes/Y or No/N";
                input.focus();
                btn.disabled = false;
                btn.classList.remove('opacity-50', 'cursor-not-allowed');
            }
        }, 1000);
    }

    // Evaluates what they typed and applies the swipe animation
    function submitDefenderDisclaimer() {
        const input = document.getElementById('defender-disclaimer-input');
        const val = input.value.trim().toLowerCase();
        
        const step1 = document.getElementById('defender-step1');
        const step2 = document.getElementById('defender-step2');

        if (val === 'yes' || val === 'y') {
            // Correct - Trigger the smooth slide left
            step1.classList.add('defender-slide-out');
            
            // Wait 250ms for the animation to fade out before swapping elements
            setTimeout(() => {
                step1.classList.add('hidden');
                step1.classList.remove('flex');
                
                // Bring in Step 2 from the right
                step2.classList.remove('hidden');
                step2.classList.add('flex', 'defender-slide-in');
            }, 250); 
            
        } else if (val === 'no' || val === 'n') {
            // Failed - Punish with 7 seconds
            startDisclaimerTimer(7);
        } else {
            // Invalid input
            input.value = "";
            input.placeholder = "Invalid. Type Yes/Y or No/N.";
        }
    }


    // PIN Schedule ------------------------------------------------------------
    const pinScheduleStorageKeys = Object.freeze({
        enabled: 'win12_pin_schedule_enabled',
        start: 'win12_pin_schedule_start',
        end: 'win12_pin_schedule_end'
    });

    let pinScheduleDraft = {
        enabled: false,
        start: 8 * 60,
        end: 22 * 60
    };

    function normalizePinScheduleMinutes(value, fallback = 0) {
        const parsed = Number.parseInt(value, 10);
        if (!Number.isFinite(parsed)) return fallback;
        return ((parsed % 1440) + 1440) % 1440;
    }

    function readPinScheduleSettings() {
        return {
            enabled: localStorage.getItem(pinScheduleStorageKeys.enabled) === 'true',
            start: normalizePinScheduleMinutes(localStorage.getItem(pinScheduleStorageKeys.start), 8 * 60),
            end: normalizePinScheduleMinutes(localStorage.getItem(pinScheduleStorageKeys.end), 22 * 60)
        };
    }

    function formatPinScheduleTime(totalMinutes) {
        const minutes = normalizePinScheduleMinutes(totalMinutes);
        const hour24 = Math.floor(minutes / 60);
        const minute = minutes % 60;
        const minuteText = String(minute).padStart(2, '0');

        if (use24HourTime) {
            return `${String(hour24).padStart(2, '0')}:${minuteText}`;
        }

        const period = hour24 >= 12 ? 'PM' : 'AM';
        const hour12 = (hour24 % 12) || 12;
        return `${hour12}:${minuteText} ${period}`;
    }

    function updatePinScheduleUI() {
        const toggle = document.getElementById('pin-schedule-toggle');
        const editor = document.getElementById('pin-schedule-editor');
        const startDisplay = document.getElementById('pin-schedule-start-display');
        const endDisplay = document.getElementById('pin-schedule-end-display');
        const status = document.getElementById('pin-schedule-status');

        if (toggle) toggle.checked = Boolean(pinScheduleDraft.enabled);
        if (editor) editor.classList.toggle('show', Boolean(pinScheduleDraft.enabled));
        if (startDisplay) startDisplay.textContent = formatPinScheduleTime(pinScheduleDraft.start);
        if (endDisplay) endDisplay.textContent = formatPinScheduleTime(pinScheduleDraft.end);

        if (status) {
            if (pinScheduleDraft.enabled) {
                status.textContent =
                    `${resolveTranslation('defPinScheduleEnabled')} · ` +
                    `${formatPinScheduleTime(pinScheduleDraft.start)} – ${formatPinScheduleTime(pinScheduleDraft.end)}`;
            } else {
                status.textContent = resolveTranslation('defPinScheduleDisabled');
            }
        }
    }

    function initializePinScheduleSettings() {
        pinScheduleDraft = readPinScheduleSettings();
        updatePinScheduleUI();
        closePinScheduleKeyPrompt();
    }

    function handlePinScheduleDraftToggle(enabled) {
        pinScheduleDraft.enabled = Boolean(enabled);
        updatePinScheduleUI();
    }

    function adjustPinScheduleTime(which, deltaMinutes) {
        if (which !== 'start' && which !== 'end') return;
        pinScheduleDraft[which] = normalizePinScheduleMinutes(pinScheduleDraft[which] + deltaMinutes);
        updatePinScheduleUI();
    }

    function cancelPinScheduleChanges() {
        pinScheduleDraft = readPinScheduleSettings();
        updatePinScheduleUI();
        closePinScheduleKeyPrompt();
    }

    function requestPinScheduleSave() {
        const overlay = document.getElementById('pin-schedule-key-overlay');
        const input = document.getElementById('pin-schedule-key-input');
        const error = document.getElementById('pin-schedule-key-error');
        if (!overlay || !input) return;

        input.value = '';
        if (error) error.classList.add('hidden');
        overlay.classList.remove('hidden');
        window.setTimeout(() => input.focus(), 60);
    }

    function closePinScheduleKeyPrompt() {
        const overlay = document.getElementById('pin-schedule-key-overlay');
        const input = document.getElementById('pin-schedule-key-input');
        const error = document.getElementById('pin-schedule-key-error');

        if (overlay) overlay.classList.add('hidden');
        if (input) input.value = '';
        if (error) error.classList.add('hidden');
    }

    function confirmPinScheduleSave() {
        const input = document.getElementById('pin-schedule-key-input');
        const error = document.getElementById('pin-schedule-key-error');
        const storedKey = localStorage.getItem('win12_def_master_key');
        if (!input || !storedKey) return;

        if (input.value !== storedKey) {
            if (error) {
                error.textContent = resolveTranslation('defIncorrectKey');
                error.classList.remove('hidden');
            }
            input.select();
            return;
        }

        localStorage.setItem(pinScheduleStorageKeys.enabled, String(Boolean(pinScheduleDraft.enabled)));
        localStorage.setItem(pinScheduleStorageKeys.start, String(normalizePinScheduleMinutes(pinScheduleDraft.start)));
        localStorage.setItem(pinScheduleStorageKeys.end, String(normalizePinScheduleMinutes(pinScheduleDraft.end)));

        closePinScheduleKeyPrompt();
        pinScheduleDraft = readPinScheduleSettings();
        updatePinScheduleUI();
        updateLoginCredentialMode();

        const status = document.getElementById('pin-schedule-status');
        if (status) {
            status.textContent = resolveTranslation('defScheduleSaved');
            window.setTimeout(() => {
                if (status.isConnected) updatePinScheduleUI();
            }, 1800);
        }
    }

    function isPinScheduleUsableNow(date = new Date()) {
        const schedule = readPinScheduleSettings();
        if (!schedule.enabled) return true;

        const hour = autoTimeEnabled ? date.getHours() : date.getUTCHours();
        const minute = autoTimeEnabled ? date.getMinutes() : date.getUTCMinutes();
        const nowMinutes = (hour * 60) + minute;
        const start = schedule.start;
        const end = schedule.end;

        if (start === end) return true;
        if (start < end) return nowMinutes >= start && nowMinutes < end;
        return nowMinutes >= start || nowMinutes < end;
    }

    function isDefenderKeyLoginMode() {
        const schedule = readPinScheduleSettings();
        return Boolean(schedule.enabled && !isPinScheduleUsableNow());
    }

    function updateLoginCredentialMode() {
        const auth = document.getElementById('auth-overlay');
        const pinInput = document.getElementById('pin-input');
        const hint = document.getElementById('login-credential-hint');
        const error = document.getElementById('pin-error');
        const policy = getEffectiveSignInPolicy();
        const signature = `${policy}|${readPinScheduleSettings().enabled}`;

        if (lastLoginPolicySignature && lastLoginPolicySignature !== signature) {
            signInSecondFactorPending = false;
            if (pinInput) pinInput.value = '';
            if (error) error.classList.add('hidden');
        }
        lastLoginPolicySignature = signature;

        const needsDefenderKey =
            policy === 'schedule-defender' ||
            policy === 'defender-only' ||
            (policy === 'pin-key' && signInSecondFactorPending);

        if (auth) auth.classList.toggle('schedule-defender-key-mode', needsDefenderKey);

        if (pinInput) {
            const translationKey = needsDefenderKey ? 'defVerifyKeyPlaceholder' : 'enterPin';
            pinInput.setAttribute('data-i18n', translationKey);
            pinInput.placeholder = resolveTranslation(translationKey);
        }

        if (hint) {
            let hintKey = '';

            if (policy === 'schedule-defender') {
                hintKey = 'defScheduleDefenderKeyRequired';
            } else if (policy === 'defender-only') {
                hintKey = 'defSignInDefenderOnlyHint';
            } else if (policy === 'pin-key' && signInSecondFactorPending) {
                hintKey = 'defSignInPinVerifiedHint';
            } else if (policy === 'pin-key') {
                hintKey = 'defSignInPinKeyHint';
            }

            if (hintKey) {
                hint.setAttribute('data-i18n', hintKey);
                hint.textContent = resolveTranslation(hintKey);
                hint.classList.remove('hidden');
            } else {
                hint.removeAttribute('data-i18n');
                hint.textContent = '';
                hint.classList.add('hidden');
            }
        }
    }


    // Sign-in protection ------------------------------------------------------
    const signInProtectionStorageKey = 'win12_signin_protection_mode';
    const signInProtectionModes = new Set(['standard', 'pin-key', 'defender-only', 'adaptive']);
    let signInProtectionDraft = 'standard';
    let signInSecondFactorPending = false;
    let lastLoginPolicySignature = '';

    function getSignInProtectionMode() {
        const stored = localStorage.getItem(signInProtectionStorageKey);
        return signInProtectionModes.has(stored) ? stored : 'standard';
    }

    function setSignInProtectionDraft(mode) {
        if (!signInProtectionModes.has(mode)) return;
        signInProtectionDraft = mode;
        updateSignInProtectionUI();
    }

    function updateSignInProtectionUI() {
        const saved = getSignInProtectionMode();

        document.querySelectorAll('#def-tab-pin .defender-signin-choice').forEach(row => {
            row.setAttribute('aria-checked', String(row.dataset.signinMode === signInProtectionDraft));
        });

        const save = document.getElementById('signin-protection-save');
        if (save) save.disabled = signInProtectionDraft === saved;
    }

    function initializeSignInProtectionSettings() {
        signInProtectionDraft = getSignInProtectionMode();
        updateSignInProtectionUI();
        closeSignInProtectionKeyPrompt();
    }

    function cancelSignInProtectionChanges() {
        signInProtectionDraft = getSignInProtectionMode();
        updateSignInProtectionUI();
        closeSignInProtectionKeyPrompt();

        const status = document.getElementById('signin-protection-status');
        if (status) status.textContent = '';
    }

    function requestSignInProtectionSave() {
        if (signInProtectionDraft === getSignInProtectionMode()) return;

        const overlay = document.getElementById('signin-protection-key-overlay');
        const input = document.getElementById('signin-protection-key-input');
        const error = document.getElementById('signin-protection-key-error');
        if (!overlay || !input) return;

        input.value = '';
        if (error) error.classList.add('hidden');
        overlay.classList.remove('hidden');
        window.setTimeout(() => input.focus(), 60);
    }

    function closeSignInProtectionKeyPrompt() {
        const overlay = document.getElementById('signin-protection-key-overlay');
        const input = document.getElementById('signin-protection-key-input');
        const error = document.getElementById('signin-protection-key-error');

        if (overlay) overlay.classList.add('hidden');
        if (input) input.value = '';
        if (error) error.classList.add('hidden');
    }

    function confirmSignInProtectionSave() {
        const input = document.getElementById('signin-protection-key-input');
        const error = document.getElementById('signin-protection-key-error');
        const defenderKey = localStorage.getItem('win12_def_master_key');
        if (!input || !defenderKey) return;

        if (input.value !== defenderKey) {
            if (error) {
                error.textContent = resolveTranslation('defIncorrectKey');
                error.classList.remove('hidden');
            }
            input.select();
            return;
        }

        localStorage.setItem(signInProtectionStorageKey, signInProtectionDraft);
        closeSignInProtectionKeyPrompt();
        initializeSignInProtectionSettings();
        resetSignInProtectionSession();
        updateLoginCredentialMode();

        const status = document.getElementById('signin-protection-status');
        if (status) {
            status.textContent = resolveTranslation('defSignInSaved');
            window.setTimeout(() => {
                if (status.isConnected) status.textContent = '';
            }, 1800);
        }
    }

    function resetSignInProtectionSession() {
        signInSecondFactorPending = false;
        lastLoginPolicySignature = '';
    }

    function getEffectiveSignInPolicy() {
        if (isDefenderKeyLoginMode()) return 'schedule-defender';

        const mode = getSignInProtectionMode();
        if (mode === 'defender-only') return 'defender-only';
        if (mode === 'pin-key') return 'pin-key';

        // Standard PIN and Adaptive both use the PIN while PIN Schedule permits it.
        return 'pin';
    }

    function verifyWindowsPinEntry(enteredPin) {
        const savedPin = localStorage.getItem('win12_pin');
        const morseEnabled = isMorsePinEnabled();

        if (!savedPin) {
            if (enteredPin.length < 4) {
                return { ok: false, message: resolveTranslation('pinMin4') };
            }

            if (morseEnabled) {
                const morse = encodePinToMorse(enteredPin);
                if (!morse) {
                    return { ok: false, message: resolveTranslation('morseUnsupported') };
                }
                localStorage.setItem(pinOptionsStorageKeys.morseOriginal, enteredPin);
                localStorage.setItem('win12_pin', morse);
            } else {
                localStorage.setItem('win12_pin', enteredPin);
            }
            return { ok: true };
        }

        let matchesStoredPin = enteredPin === savedPin;

        if (morseEnabled && !matchesStoredPin) {
            const encodedEntry = encodePinToMorse(enteredPin);
            matchesStoredPin = Boolean(encodedEntry && encodedEntry === savedPin);
        }

        let matchesLegacyEncryptedPin = false;
        if (!isBootupKeyOnlyEnabled()) {
            const today = new Date();
            const dailyKey = Math.abs(
                Math.sin(today.getFullYear() + today.getMonth() + today.getDate()) * 10000
            ).toString(16).slice(2, 6);

            let hexPin = "0";
            if (!isNaN(savedPin)) {
                hexPin = parseInt(savedPin, 10).toString(16);
            } else {
                hexPin = Array.from(savedPin)
                    .map(c => c.charCodeAt(0).toString(16))
                    .join('');
            }

            matchesLegacyEncryptedPin = enteredPin === `${dailyKey}-${hexPin}`;
        }

        return {
            ok: Boolean(matchesStoredPin || matchesLegacyEncryptedPin),
            message: resolveTranslation('incorrectPin')
        };
    }

    // Collapses Windows Security navigation to an icon-only rail, matching the native app behavior.
    function toggleDefenderSidebar(forceCollapsed) {
        const sidebar = document.getElementById('def-sidebar-container');
        const toggle = document.getElementById('def-sidebar-toggle');
        if (!sidebar || !toggle) return;

        const collapse = typeof forceCollapsed === 'boolean'
            ? forceCollapsed
            : !sidebar.classList.contains('sidebar-collapsed');

        sidebar.classList.toggle('sidebar-collapsed', collapse);
        toggle.setAttribute('aria-expanded', String(!collapse));
        toggle.setAttribute('aria-label', collapse ? 'Expand navigation' : 'Collapse navigation');
        toggle.title = collapse ? 'Expand navigation' : 'Collapse navigation';

        // Reposition the animated active marker after the rail finishes resizing.
        window.setTimeout(() => {
            const current = ['home', 'updater', 'pin'].find(name => {
                const btn = document.getElementById(`def-sidebar-btn-${name}`);
                return btn && btn.classList.contains('bg-dynamic');
            });

            if (current) switchDefenderTab(current);
        }, 210);
    }

    function initializeDefenderSidebarToggle() {
        const toggle = document.getElementById('def-sidebar-toggle');
        if (!toggle || toggle.dataset.sidebarHandlerBound === 'true') return;

        toggle.addEventListener('click', () => toggleDefenderSidebar());
        toggle.dataset.sidebarHandlerBound = 'true';
    }

    // Switches tabs and animates the global rubber-band indicator
    function switchDefenderTab(tabName) {
        const tabs = ['home', 'updater', 'pin'];
        const indicator = document.getElementById('def-active-indicator');
        const newBtn = document.getElementById(`def-sidebar-btn-${tabName}`);
        
        if (!newBtn) return;
        
        // Ensure the variable exists globally to prevent ReferenceErrors
        if (typeof window.currentDefTab === 'undefined') window.currentDefTab = null;
        
        // Calculate the exact vertical center of the clicked button
        const newTopCenter = newBtn.offsetTop + (newBtn.offsetHeight / 2);
        const finalTop = newTopCenter - 8; // 16px tall indicator (8px offset)
        
        if (defenderIndicatorAnimationTimer) {
            clearTimeout(defenderIndicatorAnimationTimer);
            defenderIndicatorAnimationTimer = null;
        }

        if (window.currentDefTab && window.currentDefTab !== tabName) {
            const oldBtn = document.getElementById(`def-sidebar-btn-${window.currentDefTab}`);
            const oldTopCenter = oldBtn ? oldBtn.offsetTop + (oldBtn.offsetHeight / 2) : newTopCenter;
            const oldTop = oldTopCenter - 8;
            const isMovingDown = finalTop > oldTop;

            indicator.style.opacity = '1';
            indicator.style.transition = 'top 0.14s cubic-bezier(.4,0,1,1), height 0.14s cubic-bezier(.4,0,1,1)';

            if (isMovingDown) {
                indicator.style.top = oldTop + 'px';
                indicator.style.height = (finalTop - oldTop + 16) + 'px';
            } else {
                indicator.style.top = finalTop + 'px';
                indicator.style.height = (oldTop - finalTop + 16) + 'px';
            }

            // Cancelable snap prevents rapid tab changes from leaving the marker
            // stretched or stranded midway between two navigation items.
            defenderIndicatorAnimationTimer = window.setTimeout(() => {
                indicator.style.transition = 'top 0.20s cubic-bezier(0,0,.2,1), height 0.20s cubic-bezier(0,0,.2,1)';
                indicator.style.top = finalTop + 'px';
                indicator.style.height = '16px';
                indicator.style.opacity = '1';
                defenderIndicatorAnimationTimer = null;
            }, 145);

        } else {
            // Instant snap for the very first load
            indicator.style.transition = 'none';
            indicator.style.top = finalTop + 'px';
            indicator.style.height = '16px';
            indicator.style.opacity = '1';
        }
        
        window.currentDefTab = tabName;

        if (tabName === 'updater') {
            const updateTypeToggle = getUpdaterSecurityToggle('type');
            if (updateTypeToggle?.checked) loadUpdateTypeManifest();
        }

        if (tabName === 'pin') {
            initializePinScheduleSettings();
            initializeSignInProtectionSettings();
        }

        // Standard pane switching logic
        tabs.forEach(t => {
            const pane = document.getElementById(`def-tab-${t}`);
            const btn = document.getElementById(`def-sidebar-btn-${t}`);
            
            if (t === tabName) {
                if (pane) { 
                    pane.classList.remove('hidden'); 
                    pane.classList.add('flex'); 
                    pane.classList.remove('app-entrance');
                    void pane.offsetWidth; 
                    pane.classList.add('app-entrance');
                }
                if (btn) btn.classList.add('bg-dynamic');
            } else {
                if (pane) { 
                    pane.classList.add('hidden'); 
                    pane.classList.remove('flex', 'app-entrance'); 
                }
                if (btn) btn.classList.remove('bg-dynamic');
            }
        });
    }

    // Updated Disclaimer Submit (Adds localStorage memory)
    function submitDefenderDisclaimer() {
        const input = document.getElementById('defender-disclaimer-input');
        const val = input.value.trim().toLowerCase();
        const step1 = document.getElementById('defender-step1');
        const step2 = document.getElementById('defender-step2');

        if (val === 'yes' || val === 'y') {
            // Save state so it never shows again!
            localStorage.setItem('win12_def_disclaimer_seen', 'true');

            step1.classList.add('defender-slide-out');
            
            setTimeout(() => {
                step1.classList.add('hidden');
                step1.classList.remove('flex');
                
                step2.classList.remove('hidden');
                step2.classList.add('flex', 'defender-slide-in');
            }, 250); 
            
        } else if (val === 'no' || val === 'n') {
            startDisclaimerTimer(7);
        } else {
            input.value = "";
            input.placeholder = "Invalid. Type Yes/Y or No/N.";
        }
    }

    // Defender key setup (single verification/setup step)
    function saveDefenderPin() {
        const pin = document.getElementById('defender-pin-input').value;
        // Save the Defender key; keep the legacy storage key for compatibility.
        localStorage.setItem('win12_def_master_key', pin);

        const step2 = document.getElementById('defender-step2');
        const main = document.getElementById('defender-main-screen');

        step2.classList.add('defender-slide-out');
        
        setTimeout(() => {
            step2.classList.add('hidden');
            step2.classList.remove('flex', 'defender-slide-in');
            
            main.classList.remove('hidden');
            main.classList.add('flex', 'defender-slide-in');
        }, 250);
    }

        // ===DEFENDER=APP=== //

