        function toggleNightMode() {
            if (nightModeLevel > 0) {
                setNightMode(0);
            } else {
                setNightMode(0.5);
                const sliderContainer = document.getElementById('night-slider-container');
                if (sliderContainer) {
                    sliderContainer.classList.remove('hidden');
                    sliderContainer.classList.add('flex');
                }
            }
        }

        function setNightMode(val) {
            nightModeLevel = parseFloat(val);
            const slider = document.getElementById('night-slider');
            if (slider) {
                slider.value = val;
                updateSliderFill(slider);
            }
            
            const mainBtn = document.getElementById('nl-main-btn');
            const mainIcon = document.getElementById('nl-main-icon');
            const mainText = document.getElementById('nl-main-text');
            const chevBtn = document.getElementById('nl-chev-btn');
            
            if (mainBtn && chevBtn) {
                if (nightModeLevel > 0) {
                    mainBtn.style.background = 'var(--selection-accent-strong)';
                    chevBtn.style.background = 'var(--selection-accent-strong)';
                    mainBtn.classList.remove('hover:bg-[var(--element-hover)]', 'bg-[var(--element-bg)]');
                    chevBtn.classList.remove('hover:bg-[var(--element-hover)]', 'bg-[var(--element-bg)]');
                    
                    if(mainIcon) { mainIcon.classList.remove('text-main'); mainIcon.style.color = '#ffffff'; }
                    if(mainText) { mainText.classList.remove('text-main'); mainText.style.color = '#ffffff'; }
                    const chevIcon = document.getElementById('nl-chev-icon');
                    if(chevIcon) { chevIcon.classList.remove('text-main'); chevIcon.style.color = '#ffffff'; }
                } else {
                    mainBtn.style.background = '';
                    chevBtn.style.background = '';
                    mainBtn.classList.add('hover:bg-[var(--element-hover)]', 'bg-[var(--element-bg)]');
                    chevBtn.classList.add('hover:bg-[var(--element-hover)]', 'bg-[var(--element-bg)]');
                    
                    if(mainIcon) { mainIcon.classList.add('text-main'); mainIcon.style.color = ''; }
                    if(mainText) { mainText.classList.add('text-main'); mainText.style.color = ''; }
                    const chevIcon = document.getElementById('nl-chev-icon');
                    if(chevIcon) { chevIcon.classList.add('text-main'); chevIcon.style.color = ''; }
                }
            }
            commitColors(false); 
        }

        function toggleNightSlider() {
            const container = document.getElementById('night-slider-container');
            if(container) {
                container.classList.toggle('hidden');
                container.classList.toggle('flex'); 
            }
        }

        function setBrightness(val) {
            const overlay = document.getElementById('brightness-overlay');
            const darkness = 1 - (val / 100);
            if(overlay) overlay.style.background = `rgba(0,0,0,${darkness})`;
            const bs = document.getElementById('brightness-slider');
            if(bs) updateSliderFill(bs);
        }

        function commitColors(save = false) {
            let r = baseGlassR, g = baseGlassG, b = baseGlassB;
            let acc = baseAccentColor;
            
            let baseLum = (0.299 * r + 0.587 * g + 0.114 * b);
            let rgbAcc = hexToRgb(acc);
            let aR = rgbAcc ? rgbAcc.r : 0, aG = rgbAcc ? rgbAcc.g : 120, aB = rgbAcc ? rgbAcc.b : 212;

            if (baseLum > 80 && nightModeLevel > 0) {
                let factor = 1 - (nightModeLevel * 0.65); 
                r = Math.floor(r * factor);
                g = Math.floor(g * factor);
                b = Math.floor(b * factor);
                aR = Math.floor(aR * factor);
                aG = Math.floor(aG * factor);
                aB = Math.floor(aB * factor);
                acc = rgbToHex(aR, aG, aB);
            }

            document.documentElement.style.setProperty('--glass-r', r);
            document.documentElement.style.setProperty('--glass-g', g);
            document.documentElement.style.setProperty('--glass-b', b);
            document.documentElement.style.setProperty('--glass-opacity', glassOpacity);
            document.documentElement.style.setProperty('--accent-color', acc);
            document.documentElement.style.setProperty('--main-color', `rgba(${r}, ${g}, ${b}, ${glassOpacity})`);
            
            let [hh, ss, ll] = rgbToHsl(aR, aG, aB);
            hh = hh - (25 / 360); 
            if (hh < 0) hh += 1;
            ll = Math.min(1, ll + 0.08); 
            let [sR, sG, sB] = hslToRgb(hh, ss, ll);
            let shiftHex = rgbToHex(sR, sG, sB);
            document.documentElement.style.setProperty('--accent-color-shift', shiftHex);

            // Derive readable content and all neutral materials directly from the selected
            // glass RGB. This is contrast calculation, not a separate light/dark theme mode.
            const srgbToLinear = (value) => {
                const c = value / 255;
                return c <= 0.04045 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4);
            };
            const glassLuminance =
                0.2126 * srgbToLinear(r) +
                0.7152 * srgbToLinear(g) +
                0.0722 * srgbToLinear(b);
            const contrastWithBlack = (glassLuminance + 0.05) / 0.05;
            const contrastWithWhite = 1.05 / (glassLuminance + 0.05);
            const ink = contrastWithBlack >= contrastWithWhite ? 18 : 255;
            const mixChannel = (glassChannel, target, amount) =>
                Math.round(glassChannel + (target - glassChannel) * amount);

            const control = [
                mixChannel(r, ink, 0.08),
                mixChannel(g, ink, 0.08),
                mixChannel(b, ink, 0.08)
            ];
            const controlHover = [
                mixChannel(r, ink, 0.14),
                mixChannel(g, ink, 0.14),
                mixChannel(b, ink, 0.14)
            ];
            const controlStrong = [
                mixChannel(r, ink, 0.20),
                mixChannel(g, ink, 0.20),
                mixChannel(b, ink, 0.20)
            ];
            const highlight = [
                mixChannel(r, 255, 0.72),
                mixChannel(g, 255, 0.72),
                mixChannel(b, 255, 0.72)
            ];

            document.documentElement.style.setProperty('--glass-ink-r', ink);
            document.documentElement.style.setProperty('--glass-ink-g', ink);
            document.documentElement.style.setProperty('--glass-ink-b', ink);
            document.documentElement.style.setProperty('--glass-control-r', control[0]);
            document.documentElement.style.setProperty('--glass-control-g', control[1]);
            document.documentElement.style.setProperty('--glass-control-b', control[2]);
            document.documentElement.style.setProperty('--glass-control-hover-r', controlHover[0]);
            document.documentElement.style.setProperty('--glass-control-hover-g', controlHover[1]);
            document.documentElement.style.setProperty('--glass-control-hover-b', controlHover[2]);
            document.documentElement.style.setProperty('--glass-control-strong-r', controlStrong[0]);
            document.documentElement.style.setProperty('--glass-control-strong-g', controlStrong[1]);
            document.documentElement.style.setProperty('--glass-control-strong-b', controlStrong[2]);
            document.documentElement.style.setProperty('--glass-highlight-r', highlight[0]);
            document.documentElement.style.setProperty('--glass-highlight-g', highlight[1]);
            document.documentElement.style.setProperty('--glass-highlight-b', highlight[2]);
            document.documentElement.style.setProperty('--lum-invert', ink === 255 ? '1' : '0');
            
            const gcp = document.getElementById('glass-color-picker');
            if(gcp) gcp.value = rgbToHex(baseGlassR, baseGlassG, baseGlassB);
            
            const acp = document.getElementById('accent-color-picker');
            if(acp) acp.value = baseAccentColor;
            
            document.querySelectorAll('.indicator').forEach(ind => {
                ind.style.background = acc;
                ind.style.boxShadow = `0 0 10px 1px ${acc}`;
            });
            
            const s1 = document.getElementById('transparency-slider');
            const s2 = document.getElementById('sm-transparency-slider');
            if(s1) updateSliderFill(s1);
            if(s2) updateSliderFill(s2);
            const ns = document.getElementById('night-slider');
            if(ns) updateSliderFill(ns);
            const bs = document.getElementById('brightness-slider');
            if(bs) updateSliderFill(bs);

            syncColorPreviewControls();

            if(save) {
                localStorage.setItem('win12_glassrgb', JSON.stringify({r: baseGlassR, g: baseGlassG, b: baseGlassB}));
                localStorage.setItem('win12_glassopacity', glassOpacity);
                localStorage.setItem('win12_accentcolor', baseAccentColor);
                
                if (recentWallpapers.length > 0) {
                    recentWallpapers[0].accent = baseAccentColor;
                    recentWallpapers[0].glass = { r: baseGlassR, g: baseGlassG, b: baseGlassB };
                    saveRecentsToIDB(recentWallpapers);
                    renderRecentWallpapers();
                }
            }
        }

        function renderRecentWallpapers() {
            const container = document.getElementById('recent-wallpapers-container');
            if(!container) return;
            container.innerHTML = '';
            
            const rootStyles = getComputedStyle(document.documentElement);
            let activeUrl = rootStyles.getPropertyValue('--wallpaper').trim();
            activeUrl = activeUrl.replace(/^url\(["']?/, '').replace(/["']?\)$/, '');
            
            recentWallpapers.forEach(wpObj => {
                const itemWrapper = document.createElement('div');
                itemWrapper.className = "relative group cursor-pointer";

                const thumb = document.createElement('div');
                // Changed h-[76px] to h-[60px] below:
                thumb.className = "recent-wp-thumb w-[120px] h-[70px] bg-cover bg-center rounded-[4px] border-2 border-transparent transition-all relative overflow-hidden group-hover:shadow-sm";
                if(wpObj.url === activeUrl) thumb.classList.add('active');
                
                thumb.style.backgroundImage = `url("${wpObj.url}")`;
                thumb.onclick = () => applyWallpaper(wpObj, true);

                const mockWindow = document.createElement('div');
                mockWindow.className = "absolute right-1 top-1 bottom-1 w-[55%] rounded-[2px] shadow-sm p-1.5 flex flex-col pointer-events-none transition-colors border border-[rgba(255,255,255,0.2)]";
                
                let glassRgba = wpObj.glass ? `rgba(${wpObj.glass.r}, ${wpObj.glass.g}, ${wpObj.glass.b}, 0.75)` : 'rgba(255,255,255,0.7)';
                mockWindow.style.background = glassRgba;
                mockWindow.style.backdropFilter = "blur(10px)";

                mockWindow.innerHTML = `
                    <div class="flex flex-col gap-[3px] mt-0.5">
                        <div class="h-[2px] w-[90%] rounded-full" style="background: var(--text-muted)"></div>
                        <div class="h-[2px] w-[100%] rounded-full" style="background: var(--text-muted)"></div>
                        <div class="h-[2px] w-[100%] rounded-full" style="background: var(--text-muted)"></div>
                        <div class="h-[2px] w-[70%] rounded-full" style="background: var(--text-muted)"></div>
                    </div>
                    <div class="mt-auto self-end w-4 h-[6px] rounded-[1.5px] shadow-sm transition-colors border border-[rgba(0,0,0,0.1)]" style="background: ${wpObj.accent || 'var(--accent-gradient)'};"></div>
                `;
                
                thumb.appendChild(mockWindow);
                itemWrapper.appendChild(thumb);
                container.appendChild(itemWrapper);
            });
        }

        async function applyWallpaper(wpObj, updateRecents = true) {
            document.documentElement.style.setProperty('--wallpaper', `url("${wpObj.url}")`);
            
            if (updateRecents) {
                recentWallpapers = recentWallpapers.filter(w => w.url !== wpObj.url);
                recentWallpapers.unshift(wpObj);
                
                if (recentWallpapers.length > 4) {
                    const removed = recentWallpapers.pop();
                    if(removed.type === 'file' && removed.url.startsWith('blob:')) {
                        URL.revokeObjectURL(removed.url); 
                    }
                } 
                await saveRecentsToIDB(recentWallpapers);
            }
            
            renderRecentWallpapers();
            applyThemeColors();
        }

        const wpUploadBtn = document.getElementById('wallpaper-upload');
        if (wpUploadBtn) {
            wpUploadBtn.addEventListener('change', function(e) {
                const file = e.target.files[0];
                if (!file) return;
                const blobUrl = URL.createObjectURL(file);
                applyWallpaper({ type: 'file', file: file, url: blobUrl, accent: baseAccentColor }, true);
            });
        }

        function applyThemeColors() {
            if (accentColorMode === 'manual') {
                commitColors(false);
                return;
            }

            const rootStyles = getComputedStyle(document.documentElement);
            let wallpaperUrl = rootStyles.getPropertyValue('--wallpaper').trim();
            wallpaperUrl = wallpaperUrl.replace(/^url\(["']?/, '').replace(/["']?\)$/, '');

            const img = new Image();
            
            if (wallpaperUrl.startsWith('blob:') || wallpaperUrl.startsWith('data:')) {
                img.removeAttribute('crossOrigin');
                img.src = wallpaperUrl;
            } else {
                img.crossOrigin = "Anonymous"; 
                if (wallpaperUrl.startsWith('http')) {
                    img.src = "https://corsproxy.io/?" + encodeURIComponent(wallpaperUrl);
                } else {
                    img.src = wallpaperUrl; 
                }
            }

            img.onerror = function() {
                baseGlassR = 255; baseGlassG = 255; baseGlassB = 255;
                baseAccentColor = '#0078D4';
                commitColors(true);
            };

            img.onload = function() {
                const canvas = document.createElement('canvas');
                canvas.width = 64; 
                canvas.height = 64;
                const ctx = canvas.getContext('2d', { willReadFrequently: true });
                
                try {
                    ctx.drawImage(img, 0, 0, 64, 64);
                    const data = ctx.getImageData(0, 0, 64, 64).data;
                    
                    let rGlass = 0, gGlass = 0, bGlass = 0;
                    let rAccent = 0, gAccent = 0, bAccent = 0;
                    let totalAccentWeight = 0;

                    for (let i = 0; i < data.length; i += 4) {
                        let pr = data[i], pg = data[i + 1], pb = data[i + 2];
                        
                        rGlass += pr; gGlass += pg; bGlass += pb;

                        let max = Math.max(pr, pg, pb);
                        let min = Math.min(pr, pg, pb);
                        let saturation = max === 0 ? 0 : (max - min) / max;
                        let weight = 1 + (saturation * 4); 

                        rAccent += pr * weight; gAccent += pg * weight; bAccent += pb * weight;
                        totalAccentWeight += weight;
                    }

                    let numPixels = data.length / 4;
                    let gray = Math.floor(0.299 * (rGlass / numPixels) + 0.587 * (gGlass / numPixels) + 0.114 * (bGlass / numPixels));
                    
                    baseGlassR = gray;
                    baseGlassG = gray;
                    baseGlassB = gray;
                    
                    if (gray > 100) {
                        baseGlassR = Math.min(255, Math.floor(baseGlassR * 1.15));
                        baseGlassG = Math.min(255, Math.floor(baseGlassG * 1.15));
                        baseGlassB = Math.min(255, Math.floor(baseGlassB * 1.15));
                    }

                    rAccent = Math.floor(rAccent / totalAccentWeight);
                    gAccent = Math.floor(gAccent / totalAccentWeight);
                    bAccent = Math.floor(bAccent / totalAccentWeight);

                    let maxColor = Math.max(rAccent, gAccent, bAccent);
                    let minColor = Math.min(rAccent, gAccent, bAccent);
                    let chroma = maxColor - minColor;
                    
                    let aR = rAccent, aG = gAccent, aB = bAccent;
                    if (chroma > 5) { 
                        let mult = 255 / (maxColor || 1);
                        aR = Math.min(255, Math.floor(rAccent * mult * 0.8 + rAccent * 0.2));
                        aG = Math.min(255, Math.floor(gAccent * mult * 0.8 + gAccent * 0.2));
                        aB = Math.min(255, Math.floor(bAccent * mult * 0.8 + bAccent * 0.2));
                    } else {
                        aR = 0; aG = 120; aB = 212; 
                    }
                    baseAccentColor = rgbToHex(aR, aG, aB);

                    commitColors(true);
                } catch (e) {
                    baseGlassR = 255; baseGlassG = 255; baseGlassB = 255;
                    baseAccentColor = '#0078D4';
                    commitColors(true); 
                }
            };
        }

        const idbConfig = { dbName: 'Win12_OS', storeName: 'wallpapers', version: 1 };

        const initDB = () => new Promise((resolve, reject) => {
            const req = indexedDB.open(idbConfig.dbName, idbConfig.version);
            req.onupgradeneeded = (e) => {
                const db = e.target.result;
                if(!db.objectStoreNames.contains(idbConfig.storeName)) {
                    db.createObjectStore(idbConfig.storeName);
                }
            };
            req.onsuccess = () => resolve(req.result);
            req.onerror = () => reject(req.error);
        });

        async function saveRecentsToIDB(recentsArr) {
            try {
                const toSave = recentsArr.map(item => {
                    if (item.type === 'file') return { type: 'file', file: item.file, accent: item.accent, glass: item.glass };
                    return { type: 'url', url: item.url, accent: item.accent, glass: item.glass };
                });
                const db = await initDB();
                const tx = db.transaction(idbConfig.storeName, 'readwrite');
                tx.objectStore(idbConfig.storeName).put(toSave, 'recents_list');
            } catch(e) {}
        }

        async function loadRecentsFromIDB() {
            try {
                const db = await initDB();
                return new Promise((resolve) => {
                    const tx = db.transaction(idbConfig.storeName, 'readonly');
                    const req = tx.objectStore(idbConfig.storeName).get('recents_list');
                    req.onsuccess = () => resolve(req.result || null);
                    req.onerror = () => resolve(null);
                });
            } catch(e) { return null; }
        }

        // Load all saved states on boot
        function loadPersistedSettings() {
            // 1. Restore custom Account Name. User-defined text is protected
            // from localization but keeps its original i18n metadata intact.
            applySavedAccountName();

            // 2. Load Paused Updates state
            const savedPauseDate = localStorage.getItem('webwindows_pause_updates_date');
            if (savedPauseDate) {
                const pauseObj = new Date(savedPauseDate + 'T12:00:00');
                const today = new Date();
                today.setHours(0, 0, 0, 0);
                
                // Only apply if the paused date hasn't already passed!
                if (pauseObj >= today) {
                    const statusText = document.getElementById('pause-updates-status');
                    const dateInput = document.getElementById('pause-date-input');
                    
                    if (dateInput) {
                        dateInput.value = savedPauseDate; // Pre-fill the calendar input
                    }
                    
                    if (statusText) {
                        const displayDate = pauseObj.toLocaleDateString(currentLang, { 
                            weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' 
                        });
                        statusText.textContent = formatTranslation('pausedUntil', { date: displayDate });
                        statusText.removeAttribute('data-i18n'); // Protect from translation engine
                    }
                } else {
                    // The paused date expired, so remove it from memory
                    localStorage.removeItem('webwindows_pause_updates_date');
                }
            }
        }
        


        // Updater Security ----------------------------------------------------
        // The updater package lives under App-Update/. Security checks are kept
        // independent so each UI switch has a concrete detector behind it.
        const updaterSecurityStorageKeys = {
            type: 'win12_updater_use_update_type',
            search: 'win12_updater_use_update_search',
            major: 'win12_updater_use_major_updates'
        };

        const updaterPackagePaths = Object.freeze({
            manifest: 'App-Update/Update_type.json',
            page: 'App-Update/index.html'
        });

        // Automatic scanning runs only while its switch is enabled. It validates
        // in the background but never opens the update modal by itself.
        const UPDATER_AUTOSCAN_INTERVAL_MS = 60000;
        let updaterAutomaticScanTimer = null;
        let lastUpdaterBypassNotice = '';
        const updaterFeatureNoticeKeys = new Map();
        const UPDATER_GOOD_NEWS_MESSAGE = () => resolveTranslation('defGoodNews');
        function getUpdaterFeatureLabel(feature) {
            const keys = {
                type: 'defUpdateTypeDetection',
                search: 'defAutomaticScanning',
                major: 'defFeatureMajorBuilds'
            };
            return resolveTranslation(keys[feature] || 'defUpdaterSecurity');
        }
        const updaterFeatureRuntimeState = new Map();
        let defenderIndicatorAnimationTimer = null;

        function setDefenderProtectionStatus(mode = 'ready', message = resolveTranslation('defProtectionRunning')) {
            const control = document.getElementById('defender-protection-status');
            const icon = document.getElementById('defender-protection-status-icon');
            const text = document.getElementById('defender-protection-status-text');
            if (!control || !icon || !text) return;

            control.classList.remove('is-checking', 'is-attention');
            if (mode === 'checking') {
                control.classList.add('is-checking');
                icon.className = 'ph ph-circle-notch';
            } else if (mode === 'attention') {
                control.classList.add('is-attention');
                icon.className = 'ph-fill ph-warning-circle';
            } else {
                icon.className = 'ph-fill ph-check-circle';
            }
            text.textContent = message;
            control.title = mode === 'checking' ? resolveTranslation('defProtectionCheckInProgress') : resolveTranslation('defRunProtectionCheck');
        }

        function refreshDefenderProtectionStatus() {
            const states = Array.from(updaterFeatureRuntimeState.values());
            if (states.some(state => state.mode === 'loading')) {
                setDefenderProtectionStatus('checking', resolveTranslation('defProtectionCheckProgress')); 
                return;
            }
            if (states.some(state => state.mode === 'error')) {
                setDefenderProtectionStatus('attention', resolveTranslation('defProtectionBlockedUpdate')); 
                return;
            }
            setDefenderProtectionStatus('ready', resolveTranslation('defProtectionRunning')); 
        }

        async function runDefenderProtectionHealthCheck() {
            const enabled = ['type', 'search', 'major'].filter(isUpdaterFeatureEnabled);
            setDefenderProtectionStatus('checking', resolveTranslation('defProtectionCheckProgress')); 

            if (!enabled.length) {
                setDefenderProtectionStatus('ready', resolveTranslation('defProtectionRunning')); 
                showSystemNotification(
                    resolveTranslation('defProtectionStatus'),
                    resolveTranslation('defCoreProtectionRunningChecksOff'),
                    'ph-shield-check',
                    { appName: resolveTranslation('defenderTitle'), severity: 'success' }
                );
                return;
            }

            const results = await Promise.all(enabled.map(feature =>
                runFocusedUpdaterDetector(feature, { forceNotice: true })
            ));

            const failed = results.some(result => result && !result.accepted && !result.noPackage);
            if (failed) {
                setDefenderProtectionStatus('attention', resolveTranslation('defProtectionBlockedUpdate')); 
            } else {
                setDefenderProtectionStatus('ready', resolveTranslation('defProtectionRunning')); 
            }
        }

        function getUpdaterSecurityToggle(feature) {
            const ids = {
                type: 'updater-use-type-toggle',
                search: 'updater-use-search-toggle',
                major: 'updater-use-major-toggle'
            };
            return document.getElementById(ids[feature]);
        }

        function isUpdaterFeatureEnabled(feature) {
            return Boolean(getUpdaterSecurityToggle(feature)?.checked);
        }

        function normalizeUpdaterText(value) {
            return String(value ?? '').replace(/\s+/g, ' ').trim();
        }

        function isReasonableUpdaterText(value, minLength, maxLength) {
            const text = normalizeUpdaterText(value);
            if (text.length < minLength || text.length > maxLength) return false;
            if (/[\u0000-\u001F\u007F]/.test(text)) return false;
            if (!/[A-Za-z0-9]/.test(text)) return false;

            // Reject common placeholder/junk values without hard-coding valid
            // update names or types. Real values are still verified against HTML.
            const lowered = text.toLowerCase();
            const junk = new Set([
                'random', 'test', 'testing', 'unknown', 'undefined', 'null',
                'placeholder', 'example', 'asdf', 'qwerty', 'n/a', 'na'
            ]);
            return !junk.has(lowered);
        }

        function isValidUpdaterBuild(value) {
            const build = normalizeUpdaterText(value);
            // WebWindows builds are numeric identifiers. Keep the rule broad
            // enough for future builds while rejecting arbitrary/random strings.
            return /^\d{5,12}$/.test(build);
        }

        function getManifestUpdates(data) {
            return Array.isArray(data?.Updates) ? data.Updates : [];
        }

        function validateUpdateTypeAndBuild(data) {
            if (!data || typeof data !== 'object' || Array.isArray(data)) {
                return { ok: false, reason: 'Update_type.json is not a valid manifest object.' };
            }

            if (!isReasonableUpdaterText(data.Update_type, 3, 80)) {
                return { ok: false, reason: 'Update_type is missing or invalid.' };
            }

            const updates = getManifestUpdates(data);
            if (!updates.length) {
                return { ok: false, reason: 'No update entries were found in Update_type.json.' };
            }

            for (let index = 0; index < updates.length; index++) {
                const update = updates[index];
                if (!update || typeof update !== 'object' || Array.isArray(update)) {
                    return { ok: false, reason: `Update entry ${index + 1} is invalid.` };
                }
                if (!isValidUpdaterBuild(update.Build)) {
                    return { ok: false, reason: `Build is missing or invalid for update entry ${index + 1}.` };
                }
            }

            return { ok: true };
        }

        function validateUpdateMetadata(data) {
            const updates = getManifestUpdates(data);
            if (!updates.length) {
                return { ok: false, reason: 'No update metadata entries were found.' };
            }

            for (let index = 0; index < updates.length; index++) {
                const update = updates[index];
                if (!update || typeof update !== 'object' || Array.isArray(update)) {
                    return { ok: false, reason: `Update metadata entry ${index + 1} is invalid.` };
                }
                if (!isReasonableUpdaterText(update.Update_name, 5, 140)) {
                    return { ok: false, reason: `Update_name is missing or invalid for entry ${index + 1}.` };
                }
                if (!isValidUpdaterBuild(update.Build)) {
                    return { ok: false, reason: `Build is missing or invalid for entry ${index + 1}.` };
                }
                if (!isReasonableUpdaterText(update.Description, 10, 1000)) {
                    return { ok: false, reason: `Description is missing or invalid for entry ${index + 1}.` };
                }
            }

            return { ok: true };
        }

        function classifyUpdaterStatus(statusValue) {
            const status = normalizeUpdaterText(statusValue).toLowerCase();
            if (status === 'verified') {
                return { ok: true, kind: 'major', label: 'Verified', display: 'Verified (Major)' };
            }
            if (status === 'non-verified') {
                return { ok: true, kind: 'minor', label: 'Non-verified', display: 'Non-verified (Minor)' };
            }
            return {
                ok: false,
                reason: 'Status must be exactly Verified or Non-verified.'
            };
        }

        function htmlContainsExactUpdaterValue(documentText, rawHtml, value, kind = 'text') {
            const expected = normalizeUpdaterText(value);
            if (!expected) return false;

            const normalizedDocument = normalizeUpdaterText(documentText).toLowerCase();
            const normalizedRaw = normalizeUpdaterText(rawHtml).toLowerCase();
            const needle = expected.toLowerCase();

            if (kind === 'build') {
                const escaped = needle.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
                const boundaryPattern = new RegExp(`(^|[^0-9])${escaped}([^0-9]|$)`);
                return boundaryPattern.test(normalizedDocument) || boundaryPattern.test(normalizedRaw);
            }

            return normalizedDocument.includes(needle) || normalizedRaw.includes(needle);
        }

        function readUpdaterHtmlMetadata(htmlText) {
            const doc = new DOMParser().parseFromString(htmlText, 'text/html');
            const bodyText = doc.body?.textContent || '';
            const titleText = doc.title || '';
            const documentText = `${titleText} ${bodyText}`;

            const metaContent = name => normalizeUpdaterText(
                doc.querySelector(`meta[name="${name}"]`)?.getAttribute('content') || ''
            );

            const dataValue = attr => normalizeUpdaterText(
                doc.querySelector(`[${attr}]`)?.getAttribute(attr) || ''
            );

            return {
                doc,
                documentText,
                explicit: {
                    name: metaContent('update-name') || dataValue('data-update-name'),
                    build: metaContent('update-build') || dataValue('data-update-build'),
                    description: metaContent('update-description') || dataValue('data-update-description')
                }
            };
        }

        function validateManifestAgainstHtml(data, htmlText) {
            const metadataCheck = validateUpdateMetadata(data);
            if (!metadataCheck.ok) return metadataCheck;

            const html = readUpdaterHtmlMetadata(htmlText);
            const updates = getManifestUpdates(data);

            for (let index = 0; index < updates.length; index++) {
                const update = updates[index];
                const name = normalizeUpdaterText(update.Update_name);
                const build = normalizeUpdaterText(update.Build);
                const description = normalizeUpdaterText(update.Description);

                // Explicit metadata is preferred when the update page provides it.
                // Otherwise the detector falls back to exact normalized page text.
                const nameMatches = html.explicit.name
                    ? html.explicit.name.toLowerCase() === name.toLowerCase()
                    : htmlContainsExactUpdaterValue(html.documentText, htmlText, name);
                const buildMatches = html.explicit.build
                    ? html.explicit.build === build
                    : htmlContainsExactUpdaterValue(html.documentText, htmlText, build, 'build');
                const descriptionMatches = html.explicit.description
                    ? html.explicit.description.toLowerCase() === description.toLowerCase()
                    : htmlContainsExactUpdaterValue(html.documentText, htmlText, description);

                if (!nameMatches) {
                    return { ok: false, reason: `Update_name does not match App-Update/index.html for entry ${index + 1}.` };
                }
                if (!buildMatches) {
                    return { ok: false, reason: `Build does not match App-Update/index.html for entry ${index + 1}.` };
                }
                if (!descriptionMatches) {
                    return { ok: false, reason: `Description does not match App-Update/index.html for entry ${index + 1}.` };
                }
            }

            return { ok: true };
        }

        async function fetchUpdaterResource(path, asJson = false) {
            const response = await fetch(path, { cache: 'no-store' });
            if (!response.ok) {
                const error = new Error(`${path} returned HTTP ${response.status}`);
                error.httpStatus = response.status;
                error.path = path;
                throw error;
            }
            return asJson ? response.json() : response.text();
        }

        // Detection results are surfaced through the system toast layer.
        // Keep only lightweight runtime state here so the Security page itself
        // stays clean and the sidebar health control can reflect scanner activity.
        function setUpdaterFeatureState(feature, message, mode = 'loading') {
            updaterFeatureRuntimeState.set(feature, {
                mode,
                message: normalizeUpdaterText(message),
                updatedAt: Date.now()
            });
            refreshDefenderProtectionStatus();
        }

        function hideUpdaterFeatureState(feature) {
            updaterFeatureRuntimeState.delete(feature);
            refreshDefenderProtectionStatus();
        }

        function setUpdateTypeState(message, mode = 'loading') {
            setUpdaterFeatureState('type', message, mode);
        }

        function resetUpdateTypeManifestUI() {
            hideUpdaterFeatureState('type');
        }

        // The old in-page manifest/status cards were removed. Validation still
        // consumes the manifest, but presentation is handled by notifications.
        function renderUpdateTypeManifest() {}

        function notifyUpdaterFeatureResult(feature, mode, message, force = false) {
            const cleanMessage = normalizeUpdaterText(message);
            if (!cleanMessage || mode === 'loading') return;

            const key = `${mode}:${cleanMessage}`;
            if (!force && updaterFeatureNoticeKeys.get(feature) === key) return;
            updaterFeatureNoticeKeys.set(feature, key);

            const title = getUpdaterFeatureLabel(feature);
            let toastMessage = cleanMessage;
            let icon = 'ph-info';

            if (mode === 'ready') {
                toastMessage = `${resolveTranslation('defDetectionVerified')}: ${cleanMessage}`;
                icon = 'ph-shield-check';
            } else if (mode === 'error') {
                toastMessage = cleanMessage.startsWith(resolveTranslation('defUpdateBypassed')) || cleanMessage.startsWith('Update bypassed:')
                    ? `${resolveTranslation('defDetectionNotVerified')}: ${cleanMessage}`
                    : `${resolveTranslation('defDetectionNotVerified')}: ${resolveTranslation('defUpdateBypassed')}: ${cleanMessage}`;
                icon = 'ph-shield-warning';
            } else if (mode === 'empty') {
                // The no-package case is a successful detector run, not an error.
                toastMessage = cleanMessage;
                icon = 'ph-check-circle';
            }

            showSystemNotification(title, toastMessage, icon, { appName: resolveTranslation('defenderTitle'), severity: mode === 'error' ? 'warning' : (mode === 'ready' || mode === 'empty' ? 'success' : 'info') });
        }

        function notifyUpdaterBypass(reason) {
            const cleanReason = normalizeUpdaterText(reason) || resolveTranslation('defUpdateValidationFailed');
            if (lastUpdaterBypassNotice === cleanReason) return;
            lastUpdaterBypassNotice = cleanReason;
            showSystemNotification(resolveTranslation('defUpdateBypassed'), cleanReason, 'ph-shield-warning', { appName: resolveTranslation('defenderTitle'), severity: 'warning' });
        }

        function clearUpdaterBypassNotice() {
            lastUpdaterBypassNotice = '';
        }

        async function runUpdaterSecurityScan({ source = 'manual', focusFeature = null } = {}) {
            const typeEnabled = isUpdaterFeatureEnabled('type');
            const searchEnabled = isUpdaterFeatureEnabled('search');
            const majorEnabled = isUpdaterFeatureEnabled('major');

            // When a switch is being tested from the Security page, only run
            // that detector. Manual/automatic updater scans run the whole chain.
            if (focusFeature === 'type') {
                setUpdateTypeState(`Checking ${updaterPackagePaths.manifest}…`, 'loading');
                try {
                    const data = await fetchUpdaterResource(updaterPackagePaths.manifest, true);
                    const check = validateUpdateTypeAndBuild(data);
                    if (!check.ok) {
                        setUpdateTypeState(`Update bypassed: ${check.reason}`, 'error');
                        return { accepted: false, noPackage: false, reason: check.reason };
                    }
                    renderUpdateTypeManifest(data);
                    setUpdateTypeState(resolveTranslation('defUpdateTypePassed'), 'ready');
                    return { accepted: true, noPackage: false, reason: '', manifest: data };
                } catch (error) {
                    const noPackage = error?.httpStatus === 404;
                    const message = noPackage
                        ? UPDATER_GOOD_NEWS_MESSAGE()
                        : `Update bypassed: ${normalizeUpdaterText(error.message)}`;
                    setUpdateTypeState(message, noPackage ? 'empty' : 'error');
                    return { accepted: false, noPackage, reason: noPackage ? 'No update manifest was found.' : normalizeUpdaterText(error.message) };
                }
            }

            if (focusFeature === 'search') {
                setUpdaterFeatureState('search', 'Checking JSON and HTML package metadata…', 'loading');
                try {
                    const [data, htmlText] = await Promise.all([
                        fetchUpdaterResource(updaterPackagePaths.manifest, true),
                        fetchUpdaterResource(updaterPackagePaths.page, false)
                    ]);
                    const check = validateManifestAgainstHtml(data, htmlText);
                    if (!check.ok) {
                        setUpdaterFeatureState('search', `Update bypassed: ${check.reason}`, 'error');
                        return { accepted: false, noPackage: false, reason: check.reason };
                    }
                    setUpdaterFeatureState('search', resolveTranslation('defMetadataMatch'), 'ready');
                    return { accepted: true, noPackage: false, reason: '', manifest: data };
                } catch (error) {
                    const noPackage = error?.httpStatus === 404;
                    const message = noPackage
                        ? UPDATER_GOOD_NEWS_MESSAGE()
                        : `Update bypassed: ${normalizeUpdaterText(error.message)}`;
                    setUpdaterFeatureState('search', message, noPackage ? 'empty' : 'error');
                    return { accepted: false, noPackage, reason: noPackage ? 'No complete App-Update package was found.' : normalizeUpdaterText(error.message) };
                }
            }

            if (focusFeature === 'major') {
                setUpdaterFeatureState('major', 'Checking Status classification…', 'loading');
                try {
                    const data = await fetchUpdaterResource(updaterPackagePaths.manifest, true);
                    const classification = classifyUpdaterStatus(data?.Status);
                    if (!classification.ok) {
                        setUpdaterFeatureState('major', `Update bypassed: ${classification.reason}`, 'error');
                        return { accepted: false, noPackage: false, reason: classification.reason };
                    }
                    setUpdaterFeatureState('major', `Status detected: ${classification.display}.`, 'ready');
                    return { accepted: true, noPackage: false, reason: '', classification, manifest: data };
                } catch (error) {
                    const noPackage = error?.httpStatus === 404;
                    const message = noPackage
                        ? UPDATER_GOOD_NEWS_MESSAGE()
                        : `Update bypassed: ${normalizeUpdaterText(error.message)}`;
                    setUpdaterFeatureState('major', message, noPackage ? 'empty' : 'error');
                    return { accepted: false, noPackage, reason: noPackage ? 'No update manifest was found.' : normalizeUpdaterText(error.message) };
                }
            }

            // Full updater scan. The HTML page and manifest must both exist before
            // an update can be exposed in Settings.
            if (typeEnabled && source !== 'automatic') {
                setUpdateTypeState(`Checking ${updaterPackagePaths.manifest}…`, 'loading');
            }
            if (searchEnabled && source !== 'automatic') {
                setUpdaterFeatureState('search', 'Checking JSON and HTML package metadata…', 'loading');
            }
            if (majorEnabled && source !== 'automatic') {
                setUpdaterFeatureState('major', 'Checking Status classification…', 'loading');
            }

            let data;
            let htmlText;
            try {
                [data, htmlText] = await Promise.all([
                    fetchUpdaterResource(updaterPackagePaths.manifest, true),
                    fetchUpdaterResource(updaterPackagePaths.page, false)
                ]);
            } catch (error) {
                const noPackage = error?.httpStatus === 404;
                const reason = noPackage
                    ? 'No complete App-Update package was found.'
                    : normalizeUpdaterText(error.message);
                const message = noPackage
                    ? UPDATER_GOOD_NEWS_MESSAGE()
                    : `Update bypassed: ${reason}`;

                if (typeEnabled) setUpdateTypeState(message, noPackage ? 'empty' : 'error');
                if (searchEnabled) setUpdaterFeatureState('search', message, noPackage ? 'empty' : 'error');
                if (majorEnabled) setUpdaterFeatureState('major', message, noPackage ? 'empty' : 'error');
                return { accepted: false, noPackage, reason };
            }

            // Detector 1: Update_type + Build validation in App-Update.
            if (typeEnabled) {
                const typeCheck = validateUpdateTypeAndBuild(data);
                if (!typeCheck.ok) {
                    setUpdateTypeState(`Update bypassed: ${typeCheck.reason}`, 'error');
                    if (searchEnabled) setUpdaterFeatureState('search', `Update bypassed: ${typeCheck.reason}`, 'error');
                    if (majorEnabled) setUpdaterFeatureState('major', `Update bypassed: ${typeCheck.reason}`, 'error');
                    notifyUpdaterBypass(typeCheck.reason);
                    return { accepted: false, noPackage: false, reason: typeCheck.reason };
                }
                renderUpdateTypeManifest(data);
                setUpdateTypeState(resolveTranslation('defUpdateTypePassed'), 'ready');
            }

            // Detector 2: JSON fields must be sane and agree with the update HTML.
            if (searchEnabled) {
                const metadataCheck = validateManifestAgainstHtml(data, htmlText);
                if (!metadataCheck.ok) {
                    setUpdaterFeatureState('search', `Update bypassed: ${metadataCheck.reason}`, 'error');
                    if (majorEnabled) setUpdaterFeatureState('major', `Update bypassed: ${metadataCheck.reason}`, 'error');
                    notifyUpdaterBypass(metadataCheck.reason);
                    return { accepted: false, noPackage: false, reason: metadataCheck.reason };
                }
                setUpdaterFeatureState('search', resolveTranslation('defMetadataMatch'), 'ready');
            }

            // Detector 3: Status is always classified before Settings exposes the
            // package. Unrecognized values are rejected. Verified means Major;
            // Major packages require the Feature & Major Builds switch.
            const classification = classifyUpdaterStatus(data?.Status);
            if (!classification.ok) {
                const reason = classification.reason;
                if (majorEnabled) setUpdaterFeatureState('major', `Update bypassed: ${reason}`, 'error');
                notifyUpdaterBypass(reason);
                return { accepted: false, noPackage: false, reason };
            }

            if (majorEnabled) {
                setUpdaterFeatureState('major', `Status detected: ${classification.display}.`, 'ready');
            }

            if (classification.kind === 'major' && !majorEnabled) {
                const reason = 'Verified (Major) update bypassed because Feature & Major Builds is turned off.';
                notifyUpdaterBypass(reason);
                return { accepted: false, noPackage: false, reason, classification };
            }

            clearUpdaterBypassNotice();
            return { accepted: true, noPackage: false, reason: '', classification, manifest: data };
        }

        async function runFocusedUpdaterDetector(feature, { forceNotice = true } = {}) {
            if (!isUpdaterFeatureEnabled(feature)) {
                hideUpdaterFeatureState(feature);
                updaterFeatureNoticeKeys.delete(feature);
                if (feature === 'type') resetUpdateTypeManifestUI();
                return null;
            }

            try {
                const scan = await runUpdaterSecurityScan({ source: 'security-page', focusFeature: feature });

                if (scan?.noPackage) {
                    notifyUpdaterFeatureResult(feature, 'empty', UPDATER_GOOD_NEWS_MESSAGE(), forceNotice);
                } else if (scan?.accepted) {
                    let message = resolveTranslation('defDetectionCompleted');
                    if (feature === 'type') message = resolveTranslation('defUpdateTypePassed');
                    if (feature === 'search') message = resolveTranslation('defMetadataMatch');
                    if (feature === 'major') {
                        message = scan.classification?.display
                            ? `Status detected: ${scan.classification.display}.`
                            : resolveTranslation('defStatusClassificationPassed');
                    }
                    notifyUpdaterFeatureResult(feature, 'ready', message, forceNotice);
                } else if (scan) {
                    notifyUpdaterFeatureResult(
                        feature,
                        'error',
                        `Update bypassed: ${normalizeUpdaterText(scan.reason) || resolveTranslation('defUpdateValidationFailed')}`,
                        forceNotice
                    );
                }

                return scan;
            } catch (error) {
                console.warn(`Updater Security: ${feature} detector failed.`, error);
                const message = `Update bypassed: ${normalizeUpdaterText(error.message)}`;
                setUpdaterFeatureState(feature, message, 'error');
                notifyUpdaterFeatureResult(feature, 'error', message, forceNotice);
                return { accepted: false, noPackage: false, reason: normalizeUpdaterText(error.message) };
            }
        }

        function stopUpdaterAutomaticScanning() {
            if (updaterAutomaticScanTimer) {
                clearInterval(updaterAutomaticScanTimer);
                updaterAutomaticScanTimer = null;
            }
        }

        async function runAutomaticUpdaterSecurityPass() {
            try {
                const scan = await runUpdaterSecurityScan({ source: 'automatic' });

                if (scan?.noPackage) {
                    notifyUpdaterFeatureResult('search', 'empty', UPDATER_GOOD_NEWS_MESSAGE());
                } else if (scan?.accepted) {
                    notifyUpdaterFeatureResult('search', 'ready', resolveTranslation('defAutomaticScanVerified'));
                }

                // Rejected packages already use notifyUpdaterBypass() in the full
                // scan path, so do not emit a second failure toast here.
                return scan;
            } catch (error) {
                console.warn('Updater Security: automatic scan failed.', error);
                notifyUpdaterFeatureResult(
                    'search',
                    'error',
                    `Update bypassed: ${normalizeUpdaterText(error.message)}`
                );
                return null;
            }
        }

        function startUpdaterAutomaticScanning() {
            stopUpdaterAutomaticScanning();
            if (!isUpdaterFeatureEnabled('search')) return;

            // Run once immediately, then continue periodically while enabled.
            runAutomaticUpdaterSecurityPass();

            updaterAutomaticScanTimer = setInterval(() => {
                if (!isUpdaterFeatureEnabled('search')) {
                    stopUpdaterAutomaticScanning();
                    return;
                }
                runAutomaticUpdaterSecurityPass();
            }, UPDATER_AUTOSCAN_INTERVAL_MS);
        }

        function handleUpdaterSecurityToggle(feature, enabled) {
            const storageKey = updaterSecurityStorageKeys[feature];
            if (!storageKey) return;

            localStorage.setItem(storageKey, String(Boolean(enabled)));

            if (!enabled) {
                hideUpdaterFeatureState(feature);
                updaterFeatureNoticeKeys.delete(feature);
                if (feature === 'type') resetUpdateTypeManifestUI();
                if (feature === 'search') stopUpdaterAutomaticScanning();
                return;
            }

            if (feature === 'search') startUpdaterAutomaticScanning();
            else runFocusedUpdaterDetector(feature);
        }

        async function loadUpdateTypeManifest() {
            return runFocusedUpdaterDetector('type');
        }

        function initializeUpdaterSecurity() {
            Object.entries(updaterSecurityStorageKeys).forEach(([feature, storageKey]) => {
                const toggle = getUpdaterSecurityToggle(feature);
                if (!toggle) return;
                toggle.checked = localStorage.getItem(storageKey) === 'true';
            });

            ['type', 'major'].forEach(feature => {
                if (isUpdaterFeatureEnabled(feature)) runFocusedUpdaterDetector(feature);
                else hideUpdaterFeatureState(feature);
            });

            if (isUpdaterFeatureEnabled('search')) startUpdaterAutomaticScanning();
            else hideUpdaterFeatureState('search');

            refreshDefenderProtectionStatus();
        }



        // WebWindows custom choice flyouts --------------------------------------
        // These controls do not use <select> at all. WebWindows owns the trigger,
        // option buttons, selected state, keyboard behavior, colors and flyout.
        let activeWinChoice = null;
        let winChoiceTrackingFrame = 0;
        let winChoiceGlobalEventsReady = false;

        const languageChoices = builtInLanguageRegistry.map(language => ({
            value: language.code,
            label: language.label,
            title: language.title,
            detail: language.detail,
            mark: language.mark
        }));

        function getWinChoiceDefinition(choiceId) {
            if (choiceId === 'language') {
                return {
                    trigger: document.querySelector('#language-choice .win-choice-trigger'),
                    valueElement: document.getElementById('language-choice-value'),
                    ariaLabel: resolveTranslation('langDisp'),
                    flyoutWidth: null,
                    value: currentLang,
                    options: languageChoices,
                    onChange: value => saveLanguageSetting(value)
                };
            }

            if (choiceId === 'taskbar-alignment') {
                const dict = translations[currentLang] || translations['en-US'];
                const horizontal = tbPosition === 'bottom' || tbPosition === 'top';
                return {
                    trigger: document.querySelector('#taskbar-alignment-choice .win-choice-trigger'),
                    valueElement: document.getElementById('taskbar-alignment-choice-value'),
                    ariaLabel: dict.taskbarAlign || 'Taskbar alignment',
                    flyoutWidth: 300,
                    value: tbAlignment,
                    options: [
                        {
                            value: 'center',
                            label: dict.center || 'Center',
                            title: dict.center || 'Center',
                            detail: resolveTranslation('taskbarAlignCenterDesc') || 'Keep taskbar icons centered',
                            icon: 'ph ph-align-center-horizontal'
                        },
                        {
                            value: 'start',
                            label: horizontal ? (dict.left || 'Left') : (dict.top || 'Top'),
                            title: horizontal ? (dict.left || 'Left') : (dict.top || 'Top'),
                            detail: resolveTranslation(horizontal ? 'taskbarAlignStartDesc' : 'taskbarAlignTopDesc') || (horizontal ? 'Align taskbar icons from the left' : 'Align taskbar icons from the top'),
                            icon: horizontal ? 'ph ph-align-left' : 'ph ph-align-top'
                        }
                    ],
                    onChange: value => handleTaskbarAlignment(value)
                };
            }

            return null;
        }

        function ensureWinChoiceFlyout() {
            let flyout = document.getElementById('win-choice-flyout');
            if (flyout) return flyout;

            flyout = document.createElement('div');
            flyout.id = 'win-choice-flyout';
            flyout.setAttribute('role', 'listbox');
            flyout.setAttribute('aria-label', resolveTranslation('chooseOption'));

            flyout.addEventListener('wheel', event => {
                const list = flyout.querySelector('.win-choice-option-list');
                if (!list || list.scrollHeight <= list.clientHeight) return;

                const before = list.scrollTop;
                list.scrollTop += event.deltaY;
                if (list.scrollTop !== before) {
                    event.preventDefault();
                    event.stopPropagation();
                }
            }, { passive: false });

            document.body.appendChild(flyout);
            return flyout;
        }

        function syncWinChoice(choiceId) {
            const definition = getWinChoiceDefinition(choiceId);
            if (!definition) return;

            const selected = definition.options.find(option => option.value === definition.value) || definition.options[0];
            if (definition.valueElement) definition.valueElement.textContent = selected?.label || '';
            if (definition.trigger) definition.trigger.setAttribute('aria-label', `${definition.ariaLabel}: ${selected?.label || ''}`);

            if (activeWinChoice?.choiceId === choiceId) {
                renderWinChoiceOptions(choiceId, { preserveFocus: true });
                positionWinChoiceFlyout();
            }
        }

        function syncAllWinChoices() {
            syncWinChoice('language');
            syncWinChoice('taskbar-alignment');
        }

        function renderWinChoiceOptions(choiceId, { preserveFocus = false } = {}) {
            const definition = getWinChoiceDefinition(choiceId);
            const flyout = ensureWinChoiceFlyout();
            if (!definition) return;

            const previousValue = preserveFocus
                ? flyout.querySelector('.win-choice-option:focus')?.dataset.value
                : null;

            flyout.replaceChildren();
            flyout.dataset.choiceId = choiceId;
            flyout.setAttribute('aria-label', definition.ariaLabel || resolveTranslation('chooseOption'));

            const list = document.createElement('div');
            list.className = 'win-choice-option-list';
            list.setAttribute('role', 'presentation');

            definition.options.forEach(option => {
                const selected = option.value === definition.value;
                const item = document.createElement('button');
                item.type = 'button';
                item.className = 'win-choice-option';
                item.setAttribute('role', 'option');
                item.setAttribute('aria-selected', String(selected));
                item.dataset.value = option.value;

                const state = document.createElement('span');
                state.className = 'win-choice-option-state';
                state.setAttribute('aria-hidden', 'true');
                state.innerHTML = '<i class="ph-fill ph-check-circle"></i>';

                const copy = document.createElement('span');
                copy.className = 'win-choice-option-copy';

                const label = document.createElement('span');
                label.className = 'win-choice-option-label';
                label.textContent = option.title || option.label;

                const detail = document.createElement('span');
                detail.className = 'win-choice-option-detail';
                detail.textContent = option.detail || option.label;

                copy.append(label, detail);
                item.append(state, copy);
                item.addEventListener('click', () => selectWinChoiceValue(choiceId, option.value));
                list.appendChild(item);
            });

            flyout.appendChild(list);

            if (preserveFocus && previousValue !== undefined) {
                const match = Array.from(flyout.querySelectorAll('.win-choice-option'))
                    .find(item => item.dataset.value === previousValue);
                match?.focus({ preventScroll: true });
            }
        }

        function positionWinChoiceFlyout() {
            if (!activeWinChoice) return;
            const { trigger } = activeWinChoice;
            const flyout = ensureWinChoiceFlyout();
            if (!trigger?.isConnected || !flyout.classList.contains('open')) return;

            const rect = trigger.getBoundingClientRect();
            const gap = 3;
            const edgePadding = 8;
            const definition = getWinChoiceDefinition(activeWinChoice.choiceId);

            // Keep Settings-owned dropdowns inside the Settings content pane.
            // This prevents the flyout from escaping below/through the app window.
            const settingsPane = trigger.closest('#settings-window .app-pane-content');
            const hostRect = settingsPane?.getBoundingClientRect() || {
                left: 0, top: 0, right: window.innerWidth, bottom: window.innerHeight,
                width: window.innerWidth, height: window.innerHeight
            };
            const bounds = {
                left: Math.max(0, hostRect.left + edgePadding),
                top: Math.max(0, hostRect.top + edgePadding),
                right: Math.min(window.innerWidth, hostRect.right - edgePadding),
                bottom: Math.min(window.innerHeight, hostRect.bottom - edgePadding)
            };

            const desiredWidth = Math.max(160, definition?.flyoutWidth || rect.width);
            const maxWidth = Math.max(160, bounds.right - bounds.left);
            flyout.style.width = `${Math.min(desiredWidth, maxWidth)}px`;

            const list = flyout.querySelector('.win-choice-option-list');
            const preservedScrollTop = list?.scrollTop || 0;

            // Do not clear the list max-height while tracking the flyout.
            // Doing so temporarily removes overflow and clamps scrollTop to 0.
            flyout.style.maxHeight = '';

            const computed = getComputedStyle(flyout);
            const verticalChrome =
                (parseFloat(computed.paddingTop) || 0) +
                (parseFloat(computed.paddingBottom) || 0) +
                (parseFloat(computed.borderTopWidth) || 0) +
                (parseFloat(computed.borderBottomWidth) || 0);
            const naturalContentHeight = list ? list.scrollHeight : flyout.scrollHeight;
            const naturalHeight = Math.min(560, Math.ceil(naturalContentHeight + verticalChrome));

            const roomBelow = Math.max(0, bounds.bottom - rect.bottom - gap);
            const roomAbove = Math.max(0, rect.top - gap - bounds.top);

            // Prefer the side that can fit the whole flyout. If neither side can,
            // use whichever side has more real space. Do not invent extra room: that
            // was what caused compact dropdowns to detach from their trigger.
            let openAbove = false;
            if (naturalHeight <= roomBelow) {
                openAbove = false;
            } else if (naturalHeight <= roomAbove) {
                openAbove = true;
            } else {
                openAbove = roomAbove > roomBelow;
            }

            const sideRoom = openAbove ? roomAbove : roomBelow;
            const availableHeight = Math.max(0, sideRoom);

            let targetListHeight = Math.max(58, availableHeight - verticalChrome);
            if (list && naturalContentHeight > targetListHeight) {
                // Snap the scroll viewport to complete option rows. This avoids the
                // ugly half-row clipping that made the final language look broken.
                const firstOption = list.querySelector('.win-choice-option');
                const rowHeight = firstOption?.getBoundingClientRect().height || 58;
                const listStyle = getComputedStyle(list);
                const rowGap = parseFloat(listStyle.rowGap || listStyle.gap) || 0;
                const fullRows = Math.max(1, Math.floor((targetListHeight + rowGap) / (rowHeight + rowGap)));
                targetListHeight = fullRows * rowHeight + Math.max(0, fullRows - 1) * rowGap;
                list.style.maxHeight = `${Math.floor(targetListHeight)}px`;
                flyout.style.maxHeight = `${Math.floor(targetListHeight + verticalChrome)}px`;
            } else {
                if (list) list.style.maxHeight = 'none';
                flyout.style.maxHeight = `${Math.min(naturalHeight, availableHeight)}px`;
            }

            // Keep the user's scroll position after layout measurements.
            if (list) {
                const maxScroll = Math.max(0, list.scrollHeight - list.clientHeight);
                list.scrollTop = Math.min(preservedScrollTop, maxScroll);
            }

            // Re-read after height constraints are applied.
            const flyoutRect = flyout.getBoundingClientRect();
            const isCompactChoice = activeWinChoice.choiceId === 'taskbar-alignment'
                || trigger.closest('.win-choice')?.classList.contains('win-choice-compact');

            // Full-width Settings choices align to the trigger's left edge. Compact
            // controls align to the trigger's right edge, like Windows menu flyouts.
            // This keeps the popup visually attached instead of drifting left when
            // the popup is wider than the small trigger button.
            const preferredLeft = isCompactChoice
                ? (rect.right - flyoutRect.width)
                : rect.left;
            const left = Math.max(
                bounds.left,
                Math.min(preferredLeft, bounds.right - flyoutRect.width)
            );

            let top;
            if (openAbove) {
                top = rect.top - flyoutRect.height - gap;
                flyout.classList.add('open-above');
            } else {
                top = rect.bottom + gap;
                flyout.classList.remove('open-above');
            }

            // Final clamp is only a safety guard. With the real-space calculation
            // above it should not need to move the flyout away from its anchor.
            top = Math.max(bounds.top, Math.min(top, bounds.bottom - flyoutRect.height));

            flyout.style.left = `${Math.round(left)}px`;
            flyout.style.top = `${Math.round(top)}px`;
        }

        function startWinChoiceTracking() {
            cancelAnimationFrame(winChoiceTrackingFrame);
            let lastLayoutSignature = '';

            const track = () => {
                if (!activeWinChoice) return;
                const trigger = activeWinChoice.trigger;
                if (!trigger?.isConnected) {
                    closeWinChoice();
                    return;
                }

                const rect = trigger.getBoundingClientRect();
                const signature = [
                    Math.round(rect.left * 10) / 10,
                    Math.round(rect.top * 10) / 10,
                    Math.round(rect.width * 10) / 10,
                    Math.round(rect.height * 10) / 10,
                    window.innerWidth,
                    window.innerHeight
                ].join('|');

                if (signature !== lastLayoutSignature) {
                    lastLayoutSignature = signature;
                    positionWinChoiceFlyout();
                }
                winChoiceTrackingFrame = requestAnimationFrame(track);
            };
            winChoiceTrackingFrame = requestAnimationFrame(track);
        }

        function openWinChoice(choiceId, trigger, { focusSelected = false } = {}) {
            const definition = getWinChoiceDefinition(choiceId);
            const actualTrigger = trigger || definition?.trigger;
            if (!definition || !actualTrigger) return;

            if (activeWinChoice?.choiceId === choiceId) {
                closeWinChoice({ restoreFocus: false });
                return;
            }

            closeWinChoice({ restoreFocus: false });
            const flyout = ensureWinChoiceFlyout();
            activeWinChoice = { choiceId, trigger: actualTrigger };
            renderWinChoiceOptions(choiceId);

            actualTrigger.setAttribute('aria-expanded', 'true');
            flyout.style.display = 'block';
            flyout.classList.remove('open', 'open-above');
            requestAnimationFrame(() => {
                if (!activeWinChoice || activeWinChoice.choiceId !== choiceId) return;
                flyout.classList.add('open');
                positionWinChoiceFlyout();
            });
            startWinChoiceTracking();

            if (focusSelected) {
                requestAnimationFrame(() => {
                    const selected = flyout.querySelector('.win-choice-option[aria-selected="true"]')
                        || flyout.querySelector('.win-choice-option');
                    selected?.focus({ preventScroll: true });
                });
            }
        }

        function toggleWinChoice(choiceId, trigger) {
            openWinChoice(choiceId, trigger);
        }

        function closeWinChoice({ restoreFocus = false } = {}) {
            if (!activeWinChoice) return;
            const flyout = ensureWinChoiceFlyout();
            const closing = activeWinChoice;
            activeWinChoice = null;
            cancelAnimationFrame(winChoiceTrackingFrame);
            winChoiceTrackingFrame = 0;

            closing.trigger?.setAttribute('aria-expanded', 'false');
            flyout.classList.remove('open', 'open-above');
            window.setTimeout(() => {
                if (!activeWinChoice) flyout.style.display = 'none';
            }, 180);
            if (restoreFocus) closing.trigger?.focus({ preventScroll: true });
        }

        function selectWinChoiceValue(choiceId, value) {
            const definition = getWinChoiceDefinition(choiceId);
            if (!definition || !definition.options.some(option => option.value === value)) return;

            const changed = definition.value !== value;
            closeWinChoice({ restoreFocus: true });
            if (changed) definition.onChange?.(value);
            syncWinChoice(choiceId);
        }

        function moveWinChoiceFocus(direction) {
            const flyout = ensureWinChoiceFlyout();
            const options = Array.from(flyout.querySelectorAll('.win-choice-option'));
            if (!options.length) return;
            const current = document.activeElement;
            let index = options.indexOf(current);
            if (direction === 'first') index = 0;
            else if (direction === 'last') index = options.length - 1;
            else if (direction > 0) index = index < 0 ? 0 : (index + 1) % options.length;
            else index = index < 0 ? options.length - 1 : (index - 1 + options.length) % options.length;
            options[index]?.focus({ preventScroll: true });
        }

        function initializeWinChoices() {
            ensureWinChoiceFlyout();
            syncAllWinChoices();

            document.querySelectorAll('.win-choice-trigger').forEach(trigger => {
                if (trigger.dataset.winChoiceKeyboardReady === 'true') return;
                trigger.dataset.winChoiceKeyboardReady = 'true';
                trigger.addEventListener('keydown', event => {
                    const host = trigger.closest('[data-win-choice]');
                    const choiceId = host?.dataset.winChoice;
                    if (!choiceId) return;
                    if (event.key === 'ArrowDown' || event.key === 'ArrowUp' || event.key === 'Enter' || event.key === ' ') {
                        event.preventDefault();
                        openWinChoice(choiceId, trigger, { focusSelected: true });
                    }
                });
            });

            if (!winChoiceGlobalEventsReady) {
                winChoiceGlobalEventsReady = true;
                document.addEventListener('pointerdown', event => {
                    if (!activeWinChoice) return;
                    const flyout = ensureWinChoiceFlyout();
                    if (flyout.contains(event.target) || activeWinChoice.trigger?.contains(event.target)) return;
                    closeWinChoice();
                }, true);

                document.addEventListener('keydown', event => {
                    if (!activeWinChoice) return;
                    const flyout = ensureWinChoiceFlyout();
                    if (event.key === 'Escape') {
                        event.preventDefault();
                        closeWinChoice({ restoreFocus: true });
                    } else if (event.key === 'ArrowDown' && flyout.contains(document.activeElement)) {
                        event.preventDefault();
                        moveWinChoiceFocus(1);
                    } else if (event.key === 'ArrowUp' && flyout.contains(document.activeElement)) {
                        event.preventDefault();
                        moveWinChoiceFocus(-1);
                    } else if (event.key === 'Home' && flyout.contains(document.activeElement)) {
                        event.preventDefault();
                        moveWinChoiceFocus('first');
                    } else if (event.key === 'End' && flyout.contains(document.activeElement)) {
                        event.preventDefault();
                        moveWinChoiceFocus('last');
                    }
                });

                window.addEventListener('resize', () => {
                    if (activeWinChoice) positionWinChoiceFlyout();
                });
                document.addEventListener('scroll', event => {
                    if (!activeWinChoice) return;
                    const flyout = ensureWinChoiceFlyout();
                    if (event.target === flyout || flyout.contains(event.target)) return;
                    positionWinChoiceFlyout();
                }, true);
            }
        }


        async function initializeSystem() {
            try {
                accentColorMode = localStorage.getItem('win12_colormode') || 'auto';
                const storedShadows = localStorage.getItem('win12_shadows');
                if (storedShadows !== null) shadowsEnabled = (storedShadows === 'true');
                
                const storedHdr = localStorage.getItem('win12_hdr');
                if (storedHdr !== null) hdrEnabled = (storedHdr === 'true');
                
                const storedGlass = localStorage.getItem('win12_glassrgb');
                if (storedGlass) {
                    const parsed = JSON.parse(storedGlass);
                    baseGlassR = parsed.r; baseGlassG = parsed.g; baseGlassB = parsed.b;
                }
                const storedOpacity = localStorage.getItem('win12_glassopacity');
                if (storedOpacity) glassOpacity = parseFloat(storedOpacity);

                const storedAccent = localStorage.getItem('win12_accentcolor');
                if (storedAccent) baseAccentColor = storedAccent;
                
                const storedLayout = localStorage.getItem('win12_taskbarlayout');
                if (storedLayout) taskbarLayout = storedLayout;

                const storedSearchLoc = localStorage.getItem('win12_searchloc');
                if (storedSearchLoc) searchLocation = storedSearchLoc;

                const storedTaskbarSearchMode = localStorage.getItem('win12_taskbar_search_mode');
                if (storedTaskbarSearchMode) taskbarSearchMode = storedTaskbarSearchMode;
                
                const storedTbPos = localStorage.getItem('win12_tbposition');
                if (storedTbPos) tbPosition = storedTbPos;
                
                const storedAlign = localStorage.getItem('win12_tbalignment');
                if (storedAlign) tbAlignment = storedAlign;
                
                const storedAutoTime = localStorage.getItem('win12_autotime');
                if (storedAutoTime !== null) autoTimeEnabled = (storedAutoTime === 'true');
                
                const storedAutoDate = localStorage.getItem('win12_autodate');
                if (storedAutoDate !== null) autoDateEnabled = (storedAutoDate === 'true');
                
                const stored24h = localStorage.getItem('win12_24hour');
                if (stored24h !== null) use24HourTime = (stored24h === 'true');
                
                const storedDynLogin = localStorage.getItem('win12_dynamic_login');
                if (storedDynLogin !== null) dynamicLoginBg = (storedDynLogin === 'true');
                else dynamicLoginBg = true;
                
                const storedLang = localStorage.getItem('win12_lang');
                if (storedLang && translations[storedLang]) currentLang = storedLang;
                
                const storedAccountName = localStorage.getItem('win12_account_name');
                if (storedAccountName) {
                    document.querySelectorAll('.user-name, [data-i18n="administrator"]').forEach(el => {
                        if(!el.hasAttribute('data-i18n') || el.getAttribute('data-i18n') === 'administrator') {
                            el.textContent = storedAccountName;
                        }
                    });
                }
            } catch(e) {}
            loadPersistedSettings();
            applyTranslations(currentLang);
            startLocalizationObserver();
            commitColors();
            setTaskbarLayout(taskbarLayout, false);
            setTaskbarSearchMode(taskbarSearchMode, false);
            setSearchLocation(searchLocation, false);
            handleTaskbarLocation(tbPosition, false);
            handleTaskbarAlignment(tbAlignment, false);
            initializeWinChoices();
            applySavedPfp();
            initializePinOptionsSettings();
            initializePinScheduleSettings();
            initializeSignInProtectionSettings();
            
            const shadowTog = document.getElementById('shadow-toggle');
            if(shadowTog) shadowTog.checked = shadowsEnabled;
            handleShadowToggle(shadowsEnabled, false);

            const hdrTog = document.getElementById('hdr-toggle');
            if (hdrTog) hdrTog.checked = hdrEnabled;
            handleHdrToggle(hdrEnabled, false);
            
            const dynLoginTog = document.getElementById('dynamic-login-bg-toggle');
            if (dynLoginTog) dynLoginTog.checked = dynamicLoginBg;
            applyLoginWallpaper();
            
            const timeAutoToggle = document.getElementById('time-auto-toggle');
            if (timeAutoToggle) timeAutoToggle.checked = autoTimeEnabled;
            
            const dateAutoToggle = document.getElementById('date-auto-toggle');
            if (dateAutoToggle) dateAutoToggle.checked = autoDateEnabled;
            
            const time24Toggle = document.getElementById('time-24h-toggle');
            if (time24Toggle) time24Toggle.checked = use24HourTime;

            const savedTimeOptionsExpanded = localStorage.getItem('win12_time_options_expanded') === 'true';
            toggleTimeOptionsFlyout(savedTimeOptionsExpanded);

            const transSlider = document.getElementById('transparency-slider');
            const smTransSlider = document.getElementById('sm-transparency-slider');
            
            if(transSlider) {
                transSlider.value = glassOpacity;
                const el1 = document.getElementById('transparency-val');
                if (el1) el1.textContent = Math.round(glassOpacity * 100) + '%';
                updateSliderFill(transSlider);
            }
            if(smTransSlider) {
                smTransSlider.value = glassOpacity;
                const el2 = document.getElementById('sm-transparency-val');
                if (el2) el2.textContent = Math.round(glassOpacity * 100) + '%';
                updateSliderFill(smTransSlider);
            }
            
            const glassColorPicker = document.getElementById('glass-color-picker');
            if(glassColorPicker) glassColorPicker.value = rgbToHex(baseGlassR, baseGlassG, baseGlassB);
            
            const accentColorPicker = document.getElementById('accent-color-picker');
            if(accentColorPicker) accentColorPicker.value = baseAccentColor;
            
            const tbLayoutTog = document.getElementById('layout-toggle');
            if (tbLayoutTog) tbLayoutTog.checked = (taskbarLayout === 'unified');
            setTaskbarSearchMode(taskbarSearchMode, false);

            const searchLocTog = document.getElementById('search-loc-toggle');
            if (searchLocTog) searchLocTog.checked = (searchLocation === 'taskbar');

            let recents = [];
            try {
                const idbRecents = await loadRecentsFromIDB();
                if (idbRecents && idbRecents.length > 0) {
                    recents = idbRecents.map(item => {
                        if (item.type === 'file' && item.file) {
                            return { type: 'file', file: item.file, url: URL.createObjectURL(item.file), accent: item.accent || '#0078D4', glass: item.glass };
                        }
                        return { type: 'url', url: item.url, accent: item.accent || '#0078D4', glass: item.glass };
                    });
                }
            } catch (e) {}

            if (recents.length === 0) {
                recents = [{ type: 'url', url: "https://wallpapercave.com/wp/wp12636488.png", accent: '#0078D4' }];
            }

            recentWallpapers = recents;
            applyWallpaper(recentWallpapers[0], false);
            
            setColorMode(accentColorMode, false);
            renderRecentWallpapers();
            renderCalendarHeaders();
            renderCalendar();
            switchSettingsTab('personalization');
            initializeUpdaterSecurity();

            const savedPin = localStorage.getItem('win12_pin');
            const pinInput = document.getElementById('pin-input');
            const loginBtn = document.getElementById('login-btn');
            const dict = translations[currentLang] || translations['en-US'];
            
            if (pinInput && loginBtn) {
                if (!savedPin) {
                    pinInput.placeholder = dict.createPin;
                    loginBtn.title = "Create PIN";
                } else {
                    pinInput.placeholder = dict.enterPin;
                    loginBtn.title = "Sign in";
                }
            }

            showLogin();
        }

        initializeDefenderSidebarToggle();
        initializeSystem();